--
-- Create procedure `sp_ValidaTokenRecuperacion`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_ValidaTokenRecuperacion (IN p_Token varchar(255))
BEGIN
  SELECT
    u.UsuarioID,
    u.Nombre,
    u.Email
  FROM Usuarios u
  WHERE u.TokenRecuperacion = p_Token
  AND u.FechaExpiracionToken >= NOW();
END
$$

--
-- Create procedure `sp_ValidarYRestablecerPassword`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_ValidarYRestablecerPassword (IN `p_Token` varchar(255),
IN `p_NuevaPassword` varchar(255))
BEGIN
  DECLARE v_UsuarioID int;
  DECLARE v_Nombre varchar(255);
  DECLARE v_Apellido varchar(255);
  DECLARE v_Email varchar(255);
  DECLARE exit_handler_activated boolean DEFAULT FALSE;

  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
  BEGIN
    SET exit_handler_activated = TRUE;
    ROLLBACK;
  END;

  SELECT
    UsuarioID,
    Nombre,
    Apellido,
    Email INTO v_UsuarioID, v_Nombre, v_Apellido, v_Email
  FROM Usuarios
  WHERE TokenRecuperacion = p_Token
  AND FechaExpiracionToken >= NOW();

  IF v_UsuarioID IS NULL THEN
    SELECT
      0 AS Codigo,
      'Token inválido o expirado' AS Mensaje,
      0 AS UsuarioID,
      '' AS Nombre,
      '' AS Apellido,
      '' AS Email;
  ELSE
    START TRANSACTION;

      UPDATE Usuarios
      SET PasswordHash = p_NuevaPassword,
          TokenRecuperacion = NULL,
          FechaExpiracionToken = NULL,
          FechaBloqueo = NULL
      WHERE UsuarioID = v_UsuarioID;

      IF exit_handler_activated THEN
        SELECT
          0 AS Codigo,
          'Error interno al actualizar' AS Mensaje,
          0 AS UsuarioID,
          '' AS Nombre,
          '' AS Apellido,
          '' AS Email;
      ELSE
        COMMIT;
        SELECT
          1 AS Codigo,
          'Contraseña actualizada exitosamente' AS Mensaje,
          v_UsuarioID AS UsuarioID,
          v_Nombre AS Nombre,
          v_Apellido AS Apellido,
          v_Email AS Email;
      END IF;
  END IF;
END
$$

--
-- Create procedure `sp_ValidarLogin`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_ValidarLogin (IN `p_Email` varchar(100), OUT `p_Codigo` int, OUT `p_Mensaje` varchar(500))
BEGIN
  DECLARE v_usuarioid int;
  DECLARE v_intentos int;
  DECLARE v_fecha_bloqueo datetime;

  UPDATE Usuarios
  SET FechaBloqueo = NULL,
      IntentosFallidos = 0
  WHERE Email = p_Email
  AND FechaBloqueo IS NOT NULL
  AND FechaBloqueo <= NOW();

  -- 1. Obtener datos básicos para validar estado
  SELECT
    UsuarioID,
    IntentosFallidos,
    FechaBloqueo INTO v_usuarioid, v_intentos, v_fecha_bloqueo
  FROM Usuarios
  WHERE Email = p_Email;

  -- 2. Validar existencia
  IF v_usuarioid IS NULL THEN
    SET p_Codigo = 0;
    SET p_Mensaje = 'El correo electrónico no está registrado.';

  -- 3. Validar Bloqueo (Si está bloqueado y aún no pasa el tiempo)
  ELSEIF v_fecha_bloqueo IS NOT NULL
    AND v_fecha_bloqueo > NOW() THEN
    SET p_Codigo = -1; -- Código especial para bloqueo
    SET p_Mensaje = 'Cuenta bloqueada temporalmente. Intente nuevamente en unos minutos.';

  -- 4. Validar si ya está verificado
  ELSEIF (SELECT
        EmailValidado
      FROM Usuarios
      WHERE Email = p_Email) = 0 THEN
    SET p_Codigo = 0;
    SET p_Mensaje = 'Debes validar tu cuenta antes de iniciar sesión.';

  ELSE
    -- Todo OK, el usuario puede intentar loguearse
    SET p_Codigo = 1;
    SET p_Mensaje = 'Ok';
  END IF;
END
$$

--
-- Create procedure `sp_RegistrarUsuario`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_RegistrarUsuario (IN `p_Nombre` varchar(100), IN `p_Apellido` varchar(100), IN `p_Email` varchar(100), IN `p_Password` varchar(255), IN `p_Telefono` varchar(20), IN `p_TokenEmail` varchar(100), IN `p_CodigoWS` varchar(10), OUT `p_codigo` int, OUT `p_mensaje` varchar(255))
BEGIN
  DECLARE v_existeEmail int DEFAULT 0;
  DECLARE v_existeTelefono int DEFAULT 0;
  DECLARE v_estaValidadoEmail int DEFAULT 0;
  DECLARE v_estaValidadoTelefono int DEFAULT 0;

  -- 1. Verificamos existencia por email y obtenemos su estado de validación
  SELECT
    COUNT(*),
    IFNULL(MAX(EmailValidado), 0) INTO v_existeEmail, v_estaValidadoEmail
  FROM Usuarios
  WHERE Email = p_Email;

  -- 2. Verificamos existencia por teléfono y obtenemos su estado de validación
  SELECT
    COUNT(*),
    IFNULL(MAX(EstaValidado), 0) INTO v_existeTelefono, v_estaValidadoTelefono
  FROM Usuarios
  WHERE Telefono = p_Telefono;

  -- Caso 1: El email ya existe y está validado
  IF v_existeEmail > 0
    AND v_estaValidadoEmail = 1 THEN
    SET p_codigo = 0;
    SET p_mensaje = 'El correo electrónico ya está registrado.';

  -- Caso 2: El teléfono existe y está validado (por otra cuenta)
  -- Nota: Verificamos que el teléfono encontrado no pertenezca al mismo email que intenta registrarse
  ELSEIF v_existeTelefono > 0
    AND v_estaValidadoTelefono = 1
    AND (SELECT
        Email
      FROM Usuarios
      WHERE Telefono = p_Telefono LIMIT 1) <> p_Email THEN
    SET p_codigo = 0;
    SET p_mensaje = 'El número de teléfono ya está registrado con otra cuenta.';

  -- Caso 3: El email existe pero NO está validado (permitimos actualizar)
  ELSEIF v_existeEmail > 0 THEN
    UPDATE Usuarios
    SET Nombre = p_Nombre,
        Apellido = p_Apellido,
        Telefono = p_Telefono,
        PasswordHash = p_Password,
        CodigoWhatsApp = p_CodigoWS,
        TokenValidacion = p_TokenEmail
    WHERE Email = p_Email;
    SET p_codigo = 1;
    SET p_mensaje = '¡Datos actualizados, revisa tu Correo o WhatsApp!';

  -- Caso 4: Nuevo registro
  ELSE
    INSERT INTO Usuarios (Nombre, Apellido, Email, PasswordHash, Telefono, TokenValidacion, CodigoWhatsApp, EstaValidado, ProveedorLogin)
      VALUES (p_Nombre, p_Apellido, p_Email, p_Password, p_Telefono, p_TokenEmail, p_CodigoWS, 0, 'Manual');

    SET p_codigo = 1;
    SET p_mensaje = '¡Registro exitoso! Revisa tu Correo o WhatsApp!';
  END IF;
END
$$

