--
-- Create procedure `sp_LoginConGoogle`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_LoginConGoogle (IN p_Email varchar(100),
IN p_Nombre varchar(100))
BEGIN
  DECLARE v_UsuarioID int;

  -- 1. Buscar si el correo ya está registrado
  SELECT
    UsuarioID INTO v_UsuarioID
  FROM Usuarios
  WHERE Email = p_Email LIMIT 1;

  -- 2. Si no existe, lo insertamos como usuario nuevo
  IF v_UsuarioID IS NULL THEN
    -- Nota: Ponemos una contraseña ficticia y lo damos por verificado
    INSERT INTO Usuarios (Nombre, Email, PasswordHash, Rol, IntentosFallidos, Verificado)
      VALUES (p_Nombre, p_Email, 'GOOGLE_AUTH_NO_PASSWORD', 'cliente', 0, 1);

    -- Capturamos el nuevo ID autoincremental
    SET v_UsuarioID = LAST_INSERT_ID();
  END IF;

  -- 3. Devolver los datos del usuario (ya sea el tuyo existente o el recién creado)
  SELECT
    UsuarioID,
    Nombre,
    Email,
    Rol
  FROM Usuarios
  WHERE UsuarioID = v_UsuarioID;
END
$$

--
-- Create procedure `sp_ActualizarUsuario`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_ActualizarUsuario (IN p_UsuarioID int,
IN p_Nombre varchar(255),
IN p_Apellido varchar(255),
IN p_Email varchar(255),
IN p_Telefono varchar(50))
BEGIN
  UPDATE Usuarios
  SET Nombre = p_Nombre,
      Apellido = p_Apellido,
      Email = p_Email,
      Telefono = p_Telefono
  WHERE UsuarioID = p_UsuarioID;
END
$$

