--
-- Create procedure `sp_ValidarSoloToken`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_ValidarSoloToken (IN p_Token varchar(255))
BEGIN
  SELECT
    u.UsuarioID,
    u.Nombre,
    u.Email
  FROM Usuarios u
    INNER JOIN sesionesactivas s
      ON u.UsuarioID = s.UsuarioID
  WHERE (u.TokenRecuperacion = p_Token
  AND u.FechaExpiracionToken >= NOW())
  OR (s.Token = p_Token
  AND s.FechaExpiracion >= NOW());
END
$$

--
-- Create procedure `sp_ObtenerUsuarioPorToken`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_ObtenerUsuarioPorToken (IN `p_Token` varchar(500))
BEGIN
  -- 1. Eliminamos las sesiones que ya han expirado
  DELETE
    FROM SesionesActivas
    WHERE FechaExpiracion < NOW();

    -- 2. Obtenemos el usuario asociado al token activo
    SELECT
      u.UsuarioId,
      u.Nombre,
      u.Rol
    FROM Usuarios u
      INNER JOIN SesionesActivas s
        ON u.UsuarioId = s.UsuarioId
    WHERE s.Token = p_Token
    AND s.FechaExpiracion > NOW();
    END
    $$

DELIMITER ;

