--
-- Create procedure `sp_ObtenerDireccionesUsuario`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_ObtenerDireccionesUsuario (IN p_UsuarioID int)
BEGIN
  SELECT
    DireccionID,
    UsuarioID,
    Alias,
    DireccionCompleta,
    Referencias,
    EsPrincipal
  FROM direcciones
  WHERE UsuarioID = p_UsuarioID
  ORDER BY EsPrincipal DESC, DireccionID ASC;
END
$$

--
-- Create procedure `sp_GuardarDireccion`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_GuardarDireccion (IN p_DireccionID int,
IN p_UsuarioID int,
IN p_Alias varchar(50),
IN p_DireccionCompleta varchar(255),
IN p_Referencias varchar(255),
IN p_EsPrincipal tinyint(1))
BEGIN
  -- Si esta dirección será la principal, quitamos el flag a las demás del usuario
  IF p_EsPrincipal = 1 THEN
    UPDATE direcciones
    SET EsPrincipal = 0
    WHERE UsuarioID = p_UsuarioID;
  END IF;

  IF p_DireccionID = 0 THEN
    -- Insertar nueva
    INSERT INTO direcciones (UsuarioID, Alias, DireccionCompleta, Referencias, EsPrincipal)
      VALUES (p_UsuarioID, p_Alias, p_DireccionCompleta, p_Referencias, p_EsPrincipal);
  ELSE
    -- Actualizar existente
    UPDATE direcciones
    SET Alias = p_Alias,
        DireccionCompleta = p_DireccionCompleta,
        Referencias = p_Referencias,
        EsPrincipal = p_EsPrincipal
    WHERE DireccionID = p_DireccionID
    AND UsuarioID = p_UsuarioID;
  END IF;
END
$$

