--
-- Create procedure `sp_ObtenerTodosLosPedidos`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_ObtenerTodosLosPedidos ()
BEGIN
  SELECT
    p.PedidoID,
    p.Total,
    p.Estado,
    p.FechaPedido AS Fecha,
    u.Nombre AS ClienteNombre,
    u.Email AS ClienteEmail
  FROM Pedidos p
    INNER JOIN Usuarios u
      ON p.UsuarioID = u.UsuarioID
  ORDER BY CASE WHEN p.Estado = 'Pendiente' THEN 1 WHEN p.Estado = 'Procesando' THEN 2 WHEN p.Estado = 'Enviado' THEN 3 ELSE 4 END ASC,
  p.FechaPedido ASC;
END
$$

--
-- Create procedure `sp_ActualizarEstadoPedido`
--
