DEFINER = 'root'@'localhost'
PROCEDURE sp_ActualizarEstadoPedido (IN p_PedidoID int,
IN p_Estado varchar(50))
BEGIN
  UPDATE Pedidos
  SET Estado = p_Estado
  WHERE PedidoID = p_PedidoID;
END
$$

