--
-- Create procedure `sp_RestarDelCarrito`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_RestarDelCarrito (IN p_UsuarioID int,
IN p_ProductoID int,
IN p_Cantidad int,
IN p_PrecioUnitario decimal(10, 2))
BEGIN
  DECLARE v_PedidoID int;
  DECLARE v_CantidadActual int;

  -- 1. Buscar si el usuario tiene un pedido "Pendiente"
  SELECT
    PedidoID INTO v_PedidoID
  FROM Pedidos
  WHERE UsuarioID = p_UsuarioID
  AND Estado = 'Pendiente' LIMIT 1;

  -- Si existe el pedido, procedemos
  IF v_PedidoID IS NOT NULL THEN

    -- 2. Consultar cuántos artículos de este producto hay actualmente en el carrito
    SELECT
      Cantidad INTO v_CantidadActual
    FROM Detalle_Pedidos
    WHERE PedidoID = v_PedidoID
    AND ProductoID = p_ProductoID LIMIT 1;

    -- Solo hacemos algo si el producto realmente está en el carrito
    IF v_CantidadActual IS NOT NULL THEN

      -- 3. Si al restarle la cantidad deseada llegamos a 0 (o menos), eliminamos el producto
      IF (v_CantidadActual - p_Cantidad) <= 0 THEN

        DELETE
          FROM Detalle_Pedidos
          WHERE PedidoID = v_PedidoID
            AND ProductoID = p_ProductoID;

          -- Ajustamos el total restando el valor total de la cantidad que realmente había
          UPDATE Pedidos
          SET Total = Total - (v_CantidadActual * p_PrecioUnitario)
          WHERE PedidoID = v_PedidoID;

          ELSE
            -- 4. Si aún quedan productos (ej. había 3 y restamos 1, quedan 2), solo restamos la cantidad
            UPDATE Detalle_Pedidos
            SET Cantidad = Cantidad - p_Cantidad
            WHERE PedidoID = v_PedidoID
            AND ProductoID = p_ProductoID;

            -- Ajustamos el total del pedido por la cantidad que restamos
            UPDATE Pedidos
            SET Total = Total - (p_Cantidad * p_PrecioUnitario)
            WHERE PedidoID = v_PedidoID;

          END IF;

          END IF;

          END IF;
          END
          $$

--
-- Create procedure `sp_RegistrarPedido`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_RegistrarPedido (IN p_UsuarioID int,
IN p_DireccionID int,
IN p_Total decimal(10, 2),
IN p_Detalles json)
BEGIN
  DECLARE v_PedidoID int;
  DECLARE v_Index int DEFAULT 0;
  DECLARE v_Count int;

  DECLARE v_ProductoID int;
  DECLARE v_Cantidad int;
  DECLARE v_Precio decimal(10, 2);

  -- Iniciar transacción
  START TRANSACTION;

    -- 1. Insertar Cabecera
    INSERT INTO Pedidos (UsuarioID, DireccionID, Total, Estado)
      VALUES (p_UsuarioID, p_DireccionID, p_Total, 'Pendiente');

    SET v_PedidoID = LAST_INSERT_ID();

    -- 2. Insertar Detalles desde JSON usando un bucle WHILE
    -- Obtenemos la cantidad de elementos en el array JSON
    SET v_Count = JSON_LENGTH(p_Detalles);

    WHILE v_Index < v_Count DO
      -- Extraer los valores individualmente usando JSON_EXTRACT
      SET v_ProductoID = CAST(JSON_UNQUOTE(JSON_EXTRACT(p_Detalles, CONCAT('$[', v_Index, '].ProductoID'))) AS UNSIGNED);
      SET v_Cantidad = CAST(JSON_UNQUOTE(JSON_EXTRACT(p_Detalles, CONCAT('$[', v_Index, '].Cantidad'))) AS UNSIGNED);
      SET v_Precio = CAST(JSON_UNQUOTE(JSON_EXTRACT(p_Detalles, CONCAT('$[', v_Index, '].Precio'))) AS decimal(10, 2));

      -- Insertar en la tabla de detalles
      INSERT INTO Detalle_Pedidos (PedidoID, ProductoID, Cantidad, PrecioUnitario)
        VALUES (v_PedidoID, v_ProductoID, v_Cantidad, v_Precio);

      -- Avanzar al siguiente elemento
      SET v_Index = v_Index + 1;
    END WHILE;

  COMMIT;

  -- Retornar el ID del pedido generado
  SELECT
    v_PedidoID AS PedidoID;
END
$$

--
-- Create procedure `sp_ObtenerDetallePedidoAdmin`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_ObtenerDetallePedidoAdmin (IN p_PedidoID int)
BEGIN
  SELECT
    p.PedidoID,
    p.Total,
    p.Estado,
    p.FechaPedido AS Fecha,
    p.MetodoPago,
    u.Nombre AS ClienteNombre,
    u.Email AS ClienteEmail,
    d.Alias,
    d.DireccionCompleta,
    d.Referencias,
    pr.Nombre AS ProductoNombre,
    dp.Cantidad,
    dp.PrecioUnitario
  FROM Pedidos p
    INNER JOIN Usuarios u
      ON p.UsuarioID = u.UsuarioID
    INNER JOIN Detalle_Pedidos dp
      ON p.PedidoID = dp.PedidoID
    INNER JOIN Productos pr
      ON dp.ProductoID = pr.Id
    LEFT JOIN Direcciones d
      ON p.DireccionID = d.DireccionID
  WHERE p.PedidoID = p_PedidoID;
END
$$

--
-- Create procedure `sp_ListarPedidos`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_ListarPedidos (IN `p_UsuarioID` int)
BEGIN
  IF p_UsuarioID IS NULL THEN
    -- Administrador: Trae todos
    SELECT
      p.*,
      d.*,
      CONCAT(u.Nombre, ' ', u.Apellido) AS NombreCliente
    FROM Pedidos p
      JOIN Usuarios u
        ON p.UsuarioID = u.UsuarioID
      JOIN Detalle_Pedidos d
        ON d.PedidoID = p.PedidoID
    ORDER BY p.FechaPedido DESC;
  ELSE
    -- Usuario: Trae solo los suyos
    SELECT
      p.*,
      d.*,
      CONCAT(u.Nombre, ' ', u.Apellido) AS NombreCliente
    FROM Pedidos p
      JOIN Usuarios u
        ON p.UsuarioID = u.UsuarioID
      JOIN Detalle_Pedidos d
        ON d.PedidoID = p.PedidoID
    WHERE p.UsuarioID = p_UsuarioID
    ORDER BY p.FechaPedido DESC;
  END IF;
END
$$

DELIMITER ;

--
-- Create table `carrito`
--
CREATE TABLE carrito (
  Id int(11) NOT NULL AUTO_INCREMENT,
  UsuarioId int(11) DEFAULT NULL,
  ProductoId int(11) DEFAULT NULL,
  Cantidad int(11) NOT NULL,
  PRIMARY KEY (Id)
)
ENGINE = INNODB,
AUTO_INCREMENT = 5,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_general_ci,
ROW_FORMAT = DYNAMIC;

--
-- Create foreign key
--
ALTER TABLE carrito
ADD CONSTRAINT Carrito_ibfk_1 FOREIGN KEY (ProductoId)
REFERENCES productos (Id);

DELIMITER $$

--
-- Create procedure `sp_ProcesarCheckout`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_ProcesarCheckout (IN p_UsuarioID int,
IN p_DireccionID int,
IN p_MetodoPago varchar(50),
OUT p_PedidoID int,
OUT p_Codigo int,
OUT p_Mensaje varchar(255))
BEGIN
  DECLARE v_Total decimal(10, 2) DEFAULT 0;
  DECLARE v_ItemsCarrito int DEFAULT 0;
  DECLARE v_ItemsInsertados int DEFAULT 0;

  -- MANEJADOR INTELIGENTE: Protege el carrito (ROLLBACK) y captura el error exacto
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 p_Mensaje = MESSAGE_TEXT;
    SET p_Codigo = -1;
    ROLLBACK;
  END;

  START TRANSACTION;

    -- 1. Calcular el total exacto del carrito y contar los items (Usando p.Id)
    SELECT
      IFNULL(SUM(c.Cantidad * p.Precio), 0),
      COUNT(c.ProductoID) INTO v_Total,
    v_ItemsCarrito
    FROM carrito c
      INNER JOIN productos p
        ON c.ProductoID = p.Id
    WHERE c.UsuarioID = p_UsuarioID;

    IF v_Total <= 0 THEN
      SET p_Codigo = 0;
      SET p_Mensaje = 'El carrito está vacío o hay un error en los precios.';
      ROLLBACK;
    ELSE
      -- 2. Crear la cabecera del pedido
      INSERT INTO pedidos (UsuarioID, FechaPedido, Total, Estado, DireccionID, MetodoPago)
        VALUES (p_UsuarioID, NOW(), v_Total, 'Pendiente', p_DireccionID, p_MetodoPago);

      SET p_PedidoID = LAST_INSERT_ID();

      -- 3. Copiar los items a detalle_pedidos congelando el precio (Usando p.Id)
      INSERT INTO detalle_pedidos (PedidoID, ProductoID, Cantidad, PrecioUnitario)
        SELECT
          p_PedidoID,
          c.ProductoID,
          c.Cantidad,
          p.Precio
        FROM carrito c
          INNER JOIN productos p
            ON c.ProductoID = p.Id
        WHERE c.UsuarioID = p_UsuarioID;

      -- 3.5. VALIDACIÓN DE INTEGRIDAD DE DATOS
      SELECT
        COUNT(*) INTO v_ItemsInsertados
      FROM detalle_pedidos
      WHERE PedidoID = p_PedidoID;

      IF v_ItemsCarrito <> v_ItemsInsertados THEN
        SET p_Codigo = -1;
        SET p_Mensaje = CONCAT('Error de integridad: Había ', v_ItemsCarrito, ' items en el carrito pero se insertaron ', v_ItemsInsertados, '.');
        ROLLBACK;
      ELSE
        -- 4. Vaciar el carrito SÓLO si la validación fue 100% exitosa
        DELETE
          FROM carrito
          WHERE UsuarioID = p_UsuarioID;

          SET p_Codigo = 1;
          SET p_Mensaje = 'Pedido generado correctamente.';
          COMMIT;
          END IF;
          END IF;
          END
          $$

--
-- Create procedure `sp_ObtenerCarritoPorUsuario`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_ObtenerCarritoPorUsuario (IN p_UsuarioID int)
BEGIN
  SELECT
    c.Id AS CarritoID, -- Cambia 'Id' por el nombre real de tu columna primaria en la tabla carrito si es diferente
    c.UsuarioID,
    c.ProductoID,
    p.Nombre AS ProductoNombre,
    c.Cantidad,
    p.Precio AS PrecioUnitario
  FROM carrito c
    INNER JOIN productos p
      ON c.ProductoId = p.Id
  WHERE c.UsuarioID = p_UsuarioID;
END
$$

--
-- Create procedure `sp_EliminarDelCarrito`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_EliminarDelCarrito (IN p_DetalleID int)
BEGIN
  DELETE
    FROM carrito
    WHERE CarritoID = p_CarritoID;
    END
    $$

--
-- Create procedure `sp_AgregarAlCarrito`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_AgregarAlCarrito (IN p_UsuarioID int,
IN p_ProductoID int,
IN p_Cantidad int,
IN p_PrecioUnitario decimal(10, 2))
BEGIN
  DECLARE v_Existe int DEFAULT 0;

  -- 1. Verificar si el producto ya está en el carrito de este usuario
  SELECT
    COUNT(*) INTO v_Existe
  FROM carrito
  WHERE UsuarioID = p_UsuarioID
  AND ProductoID = p_ProductoID;

  -- 2. Si ya existe, sumamos la cantidad
  IF v_Existe > 0 THEN
    UPDATE carrito
    SET Cantidad = Cantidad + p_Cantidad
    WHERE UsuarioID = p_UsuarioID
    AND ProductoID = p_ProductoID;
  ELSE
    -- 3. Si no existe, lo insertamos
    -- Nota: Si tu tabla carrito tiene columna para Precio, puedes agregarla en este INSERT
    INSERT INTO carrito (UsuarioID, ProductoID, Cantidad)
      VALUES (p_UsuarioID, p_ProductoID, p_Cantidad);
  END IF;

END
$$

--
-- Create procedure `sp_ActualizarCantidadCarrito`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_ActualizarCantidadCarrito (IN p_CarritoID int,
IN p_Cantidad int)
BEGIN
  UPDATE carrito
  SET Cantidad = p_Cantidad
  WHERE CarritoID = p_CarritoID;
END
$$

DELIMITER ;

